"""Remove duplicate records, keeping the first occurrence."""


def _canon(v):
    """Map any JSON-like value to a hashable structure that is == to the original.

    Unhashable values (dicts, lists) are normalized so that two values are
    equal after mapping iff they were equal before. Dict keys may themselves
    be unhashable after recursion, so items are ordered by repr for a total
    order that is independent of insertion order.
    """
    if isinstance(v, dict):
        items = [(_canon(k), _canon(val)) for k, val in v.items()]
        items.sort(key=repr)
        return ('d', tuple(items))
    if isinstance(v, list):
        return ('l', tuple(_canon(x) for x in v))
    if isinstance(v, tuple):
        return ('t', tuple(_canon(x) for x in v))
    if v is None or isinstance(v, (str, int, float, bool)):
        return v
    if isinstance(v, (set, frozenset)):
        return ('s', frozenset(_canon(x) for x in v))
    return ('o', repr(v))


def dedupe(records, key=None):
    seen = set()
    out = []
    for r in records:
        k = key(r) if key is not None else r
        k = _canon(k)
        if k not in seen:
            seen.add(k)
            out.append(r)
    return out
EOF
